def case_table(rows):
 s='<table class="cases"><thead><tr><th class="id">编号</th><th class="label">注入工况 / 验证目的</th><th class="status">预期 = 实测</th></tr></thead><tbody>'
 for r in rows:
  status=r['status'];short={'INCONCLUSIVE':'待复核','ERROR':'拒绝配置'}.get(status,status)
  s+=f'<tr><td><b>{r["id"][:3]}</b></td><td>{escape(r["name"])}</td><td class="label{status[0]}">{short} · ✓</td></tr>'
 return s+'</tbody></table>'

